// dependency_extractor.rs - Extract full dependency paths for binaries like rustc
// Generated by step4_bootstrap - Dependency Path Extraction

use std::fs;
use std::path::Path;
// use std::process::Command;  // Commented out - unused
use anyhow::Result;

pub struct DependencyPath {
    pub name: String,
    pub version: String,
    pub path: String,
    pub source: String, // git, crates.io, local
}

pub fn extract_cargo_dependencies(cargo_toml_path: &str) -> Result<Vec<DependencyPath>> {
    let content = fs::read_to_string(cargo_toml_path)?;
    let mut deps = Vec::new();
    
    let parsed: toml::Value = content.parse()?;
    
    // Extract dependencies section
    if let Some(dependencies) = parsed.get("dependencies").and_then(|d| d.as_table()) {
        for (name, dep_info) in dependencies {
            let dep_path = extract_dependency_path(name, dep_info)?;
            deps.push(dep_path);
        }
    }
    
    // Extract dev-dependencies
    if let Some(dev_deps) = parsed.get("dev-dependencies").and_then(|d| d.as_table()) {
        for (name, dep_info) in dev_deps {
            let dep_path = extract_dependency_path(name, dep_info)?;
            deps.push(dep_path);
        }
    }
    
    Ok(deps)
}

pub fn extract_dependency_path(name: &str, dep_info: &toml::Value) -> Result<DependencyPath> {
    match dep_info {
        toml::Value::String(version) => {
            Ok(DependencyPath {
                name: name.to_string(),
                version: version.clone(),
                path: format!("~/.cargo/registry/src/index.crates.io-*/{}*", name),
                source: "crates.io".to_string(),
            })
        },
        toml::Value::Table(table) => {
            if let Some(path) = table.get("path").and_then(|p| p.as_str()) {
                Ok(DependencyPath {
                    name: name.to_string(),
                    version: "local".to_string(),
                    path: path.to_string(),
                    source: "local".to_string(),
                })
            } else if let Some(git) = table.get("git").and_then(|g| g.as_str()) {
                let git_path = format!("~/.cargo/git/checkouts/{}-*/", 
                                     git.split('/').last().unwrap_or(name));
                Ok(DependencyPath {
                    name: name.to_string(),
                    version: table.get("rev").or(table.get("branch")).or(table.get("tag"))
                        .and_then(|v| v.as_str()).unwrap_or("HEAD").to_string(),
                    path: git_path,
                    source: "git".to_string(),
                })
            } else if let Some(version) = table.get("version").and_then(|v| v.as_str()) {
                Ok(DependencyPath {
                    name: name.to_string(),
                    version: version.to_string(),
                    path: format!("~/.cargo/registry/src/index.crates.io-*/{}*", name),
                    source: "crates.io".to_string(),
                })
            } else {
                Ok(DependencyPath {
                    name: name.to_string(),
                    version: "unknown".to_string(),
                    path: "unknown".to_string(),
                    source: "unknown".to_string(),
                })
            }
        },
        _ => Ok(DependencyPath {
            name: name.to_string(),
            version: "unknown".to_string(),
            path: "unknown".to_string(),
            source: "unknown".to_string(),
        })
    }
}

pub fn get_rustc_dependencies() -> Result<Vec<DependencyPath>> {
    // Look for rustc in the actual rust repository structure
    let rustc_paths = vec![
        "../../rust/compiler/rustc/Cargo.toml",
        "../../rust/compiler/rustc_driver/Cargo.toml",
        "../../rust/compiler/rustc_middle/Cargo.toml",
        "../../rust/compiler/rustc_codegen_ssa/Cargo.toml",
        "../../rust/compiler/rustc_interface/Cargo.toml",
        "../rust/compiler/rustc/Cargo.toml",
        "../rust/compiler/rustc_driver/Cargo.toml",
        "../rust/compiler/rustc_middle/Cargo.toml",
    ];
    
    let mut all_deps = Vec::new();
    
    // Automatically discover all rustc compiler components
    let compiler_dir = std::path::Path::new("../rust/compiler");
    if compiler_dir.exists() {
        for entry in std::fs::read_dir(compiler_dir).unwrap_or_else(|_| std::fs::read_dir(".").unwrap()) {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                        // Check if it has a Cargo.toml (is a crate)
                        let cargo_toml = path.join("Cargo.toml");
                        if cargo_toml.exists() {
                            all_deps.push(DependencyPath {
                                name: name.to_string(),
                                version: "0.0.0".to_string(),
                                path: format!("../rust/compiler/{}", name),
                                source: "local".to_string(),
                            });
                        }
                    }
                }
            }
        }
    }
    
    // Automatically discover all library components (except std - save for last)
    let library_dir = std::path::Path::new("../rust/library");
    if library_dir.exists() {
        for entry in std::fs::read_dir(library_dir).unwrap_or_else(|_| std::fs::read_dir(".").unwrap()) {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                        // Skip std for now - add it last
                        if name == "std" {
                            continue;
                        }
                        
                        // Check if it has a Cargo.toml (is a crate)
                        let cargo_toml = path.join("Cargo.toml");
                        if cargo_toml.exists() {
                            all_deps.push(DependencyPath {
                                name: name.to_string(),
                                version: "0.0.0".to_string(),
                                path: format!("../rust/library/{}", name),
                                source: "std".to_string(),
                            });
                        }
                    }
                }
            }
        }
    }
    
    // Add std library LAST to ensure it takes priority in symbol conflicts
    all_deps.push(DependencyPath {
        name: "std".to_string(),
        version: "0.0.0".to_string(),
        path: "../rust/library/std".to_string(),
        source: "std".to_string(),
    });
    
    Ok(all_deps)
}

#[macro_export]
macro_rules! mkdeps_paths {
    ($binary:expr) => {{
        match $binary {
            "rustc" => get_rustc_dependencies().unwrap_or_default(),
            _ => {
                let cargo_path = format!("../{}/Cargo.toml", $binary);
                extract_cargo_dependencies(&cargo_path).unwrap_or_default()
            }
        }
    }};
}

#[macro_export]
macro_rules! mkfull_dep_tree {
    ($binary:expr) => {{
        let deps = mkdeps_paths!($binary);
        println!("🔍 Full dependency tree for {}:", $binary);
        for dep in &deps {
            println!("  📦 {} v{} → {} ({})", dep.name, dep.version, dep.path, dep.source);
        }
        deps
    }};
}
